export const TOKEN_KEY = "runable.managed-auth.token";
const NONCE_KEY = "runable.managed-auth.nonce";

/** Where a platform client keeps the app's bearer session token ("" when signed out). */
export interface TokenStore {
  getToken(): string;
  setToken(token: string): void;
  clearToken(): void;
}

// All browser-storage access lives here: the app's bearer token (localStorage, persists — web
// pages and Electron renderers) and the single-use CSRF nonce that survives the web flow's
// top-level redirect (sessionStorage). Access is lazy, so bundlers may include this on platforms
// without these globals as long as it is never called there.
class BrowserStorage implements TokenStore {
  getToken() {
    return localStorage.getItem(TOKEN_KEY) ?? "";
  }
  setToken(token: string) {
    localStorage.setItem(TOKEN_KEY, token);
  }
  clearToken() {
    localStorage.removeItem(TOKEN_KEY);
  }
  setNonce(nonce: string) {
    sessionStorage.setItem(NONCE_KEY, nonce);
  }
  takeNonce() {
    const nonce = sessionStorage.getItem(NONCE_KEY);
    sessionStorage.removeItem(NONCE_KEY);
    return nonce ?? undefined;
  }
}

export const browserStorage = new BrowserStorage();
